const ConsistentRevenue: React.FC<ConsistentRevenueProps> = ({
  backgroundColor = "#09090b",
  primaryColor = "#6366f1",
  accentColor = "#2dd4bf",
  transparentBackground = false,
  durationInSeconds = 30,
  headline = "Consistent Revenue",
  subheadline = "comes from Systems.",
  pillars = [
    { title: "Ads.", iconName: "BarChart" },
    { title: "Automations.", iconName: "Cpu" },
    { title: "Pricing.", iconName: "DollarSign" },
    { title: "And Client Retention.", iconName: "Users" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Background Animation Math (Deterministic based on frame)
  const bgOpacity = interpolate(frame, [0, 45], [0, 1], { extrapolateRight: "clamp" });
  const orb1X = -width * 0.1 + Math.sin(frame / 60) * 80;
  const orb1Y = height * 0.2 + Math.cos(frame / 70) * 120;
  const orb2X = width * 1.1 + Math.cos(frame / 50) * -100;
  const orb2Y = height * 0.8 + Math.sin(frame / 45) * -150;

  // Header Animation Math
  const headSpring = spring({ fps, frame: frame - 10, config: { damping: 16, mass: 0.8 } });
  const subSpring = spring({ fps, frame: frame - 25, config: { damping: 14, mass: 0.8 } });
  
  // Fade headers out to leave the center screen alone
  const headerOutSpring = spring({ fps, frame: frame - 60, config: { damping: 15, mass: 0.9 } });

  const headY = interpolate(headSpring, [0, 1], [40, 0]) + interpolate(headerOutSpring, [0, 1], [0, -40]);
  const subY = interpolate(subSpring, [0, 1], [30, 0]) + interpolate(headerOutSpring, [0, 1], [0, -40]);
  
  const headOpacity = Math.max(0, headSpring - headerOutSpring);
  const subOpacity = Math.max(0, subSpring - headerOutSpring);

  // Pillar Sequence Math
  const pillarsStartFrame = 85;
  const totalFrames = durationInSeconds * fps;
  const availableFrames = Math.max(30, totalFrames - pillarsStartFrame);
  const framesPerPillar = availableFrames / pillars.length;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
      }}
    >
      {/* Background Orbs */}
      <div
        style={{
          position: "absolute",
          width: width * 0.9,
          height: width * 0.9,
          borderRadius: "50%",
          backgroundColor: primaryColor,
          filter: "blur(200px)",
          opacity: 0.15 * bgOpacity,
          top: orb1Y,
          left: orb1X,
          transition: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          width: width * 0.7,
          height: width * 0.7,
          borderRadius: "50%",
          backgroundColor: accentColor,
          filter: "blur(180px)",
          opacity: 0.12 * bgOpacity,
          top: orb2Y,
          left: orb2X - width * 0.7,
          transition: "none",
        }}
      />

      {/* Main Content Container (Headers) */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          width: width * 0.85,
          alignSelf: "center",
          marginTop: height * 0.15,
          zIndex: 10,
        }}
      >
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <h1
            style={{
              fontSize: 76,
              fontWeight: 800,
              color: "white",
              margin: 0,
              lineHeight: 1.1,
              letterSpacing: "-0.02em",
              transform: `translateY(${headY}px)`,
              opacity: headOpacity,
              transition: "none",
            }}
          >
            {headline}
          </h1>
          <h2
            style={{
              fontSize: 48,
              fontWeight: 500,
              color: accentColor,
              margin: 0,
              lineHeight: 1.2,
              transform: `translateY(${subY}px)`,
              opacity: subOpacity,
              transition: "none",
            }}
          >
            {subheadline}
          </h2>
        </div>
      </div>

      {/* Pillars Full Screen Container */}
      <div 
        style={{ 
          position: 'absolute', 
          inset: 0, 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'center', 
          zIndex: 20,
        }}
      >
        {pillars.map((item, index) => {
          const isLast = index === pillars.length - 1;
          const pillarStartFrame = pillarsStartFrame + index * framesPerPillar;
          const pillarEndFrame = pillarStartFrame + framesPerPillar;
          
          const transitionFrames = Math.min(20, framesPerPillar * 0.4);
          const outFrame = isLast ? totalFrames - transitionFrames : pillarEndFrame - transitionFrames;

          const pillarIn = spring({
            fps,
            frame: frame - pillarStartFrame,
            config: { damping: 15, mass: 0.9 },
          });
          
          const pillarOut = spring({
            fps,
            frame: frame - outFrame,
            config: { damping: 15, mass: 0.9 },
          });

          const pillarY = interpolate(pillarIn, [0, 1], [60, 0]) + interpolate(pillarOut, [0, 1], [0, -60]);
          const scale = interpolate(pillarIn, [0, 1], [0.8, 1]) + interpolate(pillarOut, [0, 1], [0, 0.1]); 
          const opacity = Math.max(0, Math.min(1, pillarIn - pillarOut));

          return (
            <div
              key={`pillar-${index}`}
              style={{
                position: "absolute",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                transform: `translateY(${pillarY}px) scale(${scale})`,
                opacity,
                transition: "none",
              }}
            >
              <div
                style={{
                  color: primaryColor,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  marginBottom: 48,
                  transition: "none",
                }}
              >
                <Icon name={item.iconName} size={180} />
              </div>
              <div
                style={{
                  fontSize: 84,
                  fontWeight: 700,
                  color: "white",
                  letterSpacing: "-0.02em",
                  textAlign: "center",
                  lineHeight: 1.1,
                  maxWidth: width * 0.85,
                }}
              >
                {item.title}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default ConsistentRevenue;